/** Public pages coexist with the reader's existing hash routes and callbacks. */
export const STUDY_URL = '/study/';
export const SIGNUP_URL = '/study/#/login?mode=signup';
export const LOGIN_URL = '/study/#/login';

export function isPublicHome(pathname: string, hash: string): boolean {
  return pathname === '/' && !hash.startsWith('#/');
}

export function isPublicPage(pathname: string, hash: string): boolean {
  return (
    isPublicHome(pathname, hash) ||
    /^\/blog(?:\/|$)/.test(pathname) ||
    /^\/(privacy-policy|terms-of-service|about|resources|contact)\/?$/.test(pathname)
  );
}

/** Never interpolate a caller-supplied redirect into navigation. */
export function getLoginDestination(search: string): string {
  const params = new URLSearchParams(search);
  const destination = params.get('redirect');
  if (destination === 'subscribe') {
    return '/subscribe';
  }
  if (destination === 'profile') {
    return '/profile';
  }
  return '/';
}
